mapper.select:
SELECT c.id, c.name, c.introduce, c.avatar, c.category_id AS categoryId, c.create_time AS createTime, c.address, ST_Y(c.location) AS longitude, ST_X(c.location) AS latitude, u.nickname AS hostNickname, u.avatar AS hostAvatar FROM sys_intcircle c JOIN sys_user u ON c.create_user = u.id JOIN sys_user_intcircle uc ON uc.intcircle_id = c.id
category_id=#{categoryId}
ORDER BY c.update_time DESC
